{
  "implementation": "def solve(case):
    capacity = case['capacity']
    trials = case['trials']
    cache = {}  # signature -> {last_trial, reflection, success}
    signatures = []

    for i, trial in enumerate(trials):
        sig = trial['signature']
        signatures.append(sig)
        # update cache
        cache[sig] = {
            'last_trial': i,
            'reflection': trial['reflection'],
            'success': trial['success']
        }
        # evict if over capacity
        if len(cache) > capacity:
            # find signature with minimum last_trial
            min_sig = min(cache, key=lambda s: cache[s]['last_trial'])
            del cache[min_sig]

    # build memory list sorted by last_trial (optional, but deterministic)
    memory = [
        {
            'signature': sig,
            'last_trial': entry['last_trial'],
            'reflection': entry['reflection'],
            'success': entry['success']
        }
        for sig, entry in sorted(cache.items(), key=lambda item: item[1]['last_trial'])
    ]

    return {
        'memory': memory,
        'signatures': signatures
    }"
}
